<script setup>
import { reactive, ref } from 'vue';
import { useTraceabilityWorkspace } from './modules/traceability/presentation/composables/useTraceabilityWorkspace.js';
import CaptureSyncStatus from './modules/traceability/presentation/components/CaptureSyncStatus.vue';
const {identity,captures,lot,error,notice,online,busy,qr,sessionVerified,login,logout,capture,synchronize,lookup}=useTraceabilityWorkspace();
const email=ref(''),password=ref(''),lookupId=ref('');
const form=reactive({mineralType:'Gold',weight:'',weightUnit:'kg',reference:'',source:''});
async function submitLogin(){await login(email.value,password.value);password.value='';}
async function submitCapture(){if(await capture({mineralType:form.mineralType,weight:form.weight,weightUnit:form.weightUnit,originEvidence:{reference:form.reference,source:form.source}})){form.weight='';form.reference='';}}
</script>
<template>
<main class="workspace">
<header class="topbar"><div><p class="eyebrow">XTRACTA · TRAZABILIDAD MINERAL</p><h1>EventOre</h1></div><span :class="['connection',online?'connected':'offline']">{{online?'Con conexión':'Sin conexión'}}</span></header>
<p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p>
<section v-if="!identity" class="panel login"><h2>Accede a tu organización</h2><p>Usa la cuenta provisionada por el administrador para registrar y consultar lotes.</p><form @submit.prevent="submitLogin"><label>Correo<input v-model="email" type="email" autocomplete="username" required /></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required maxlength="128" /></label><button :disabled="busy||!online">{{busy?'Ingresando…':'Iniciar sesión'}}</button></form></section>
<template v-else>
<section class="account"><div><strong>{{identity.email}}</strong><p>Organización {{identity.tenantId}}</p><small v-if="!sessionVerified">La sesión debe verificarse al recuperar conexión.</small></div><button class="secondary" @click="logout" :disabled="!online">Cerrar sesión</button></section>
<div class="columns"><section class="panel"><h2>Registrar lote</h2><p>La captura se conserva localmente antes de enviarse al servidor.</p><form @submit.prevent="submitCapture"><label>Mineral<input v-model="form.mineralType" required maxlength="100" /></label><div class="formrow"><label>Peso<input v-model="form.weight" type="text" inputmode="decimal" placeholder="125.50" required /></label><label>Unidad<select v-model="form.weightUnit"><option>g</option><option>kg</option><option>t</option></select></label></div><label>Referencia de evidencia<input v-model="form.reference" required maxlength="500" /></label><label>Fuente declarada<input v-model="form.source" required maxlength="500" /></label><button :disabled="busy">{{busy?'Guardando…':'Guardar captura'}}</button></form><p class="muted">La evidencia queda pendiente de revisión. Registrar un lote no verifica su procedencia.</p></section>
<section class="panel"><h2>Consultar lote</h2><form @submit.prevent="lookup(lookupId)"><label>Identificador del lote<input v-model="lookupId" placeholder="UUID del lote" required /></label><button :disabled="!online">Consultar</button></form><div v-if="lot" class="lot"><h3>{{lot.mineralType}} · {{lot.weight}} {{lot.weightUnit}}</h3><p class="identifier">{{lot.lotId}}</p><dl><dt>Estado</dt><dd>{{lot.status}}</dd><dt>Evidencia</dt><dd>{{lot.originEvidenceStatus}}</dd><dt>Versión</dt><dd>{{lot.version}}</dd></dl><p v-if="lot.status==='Cancelled'" class="alert error">Lote cancelado. No habilitado para transporte.</p><img v-if="qr" :src="qr" alt="Código QR para consultar este lote" width="180" height="180" /><p class="muted">El QR identifica el registro; no certifica autenticidad ni origen ético.</p></div></section></div>
<section class="panel"><div class="sectionhead"><h2>Capturas de este dispositivo</h2><button class="secondary" @click="synchronize" :disabled="!online||busy">Sincronizar pendientes</button></div><p v-if="!captures.length">Todavía no hay capturas para esta organización.</p><ul class="captures"><li v-for="item in captures" :key="item.clientEventId"><div><strong>{{item.payload.mineralType}} · {{item.payload.weight}} {{item.payload.weightUnit}}</strong><p class="identifier">{{item.clientEventId}}</p><CaptureSyncStatus :status="item.status" :reason="item.reason??''" /></div><button v-if="item.lotId" class="secondary" @click="lookup(item.lotId)" :disabled="!online">Ver lote</button></li></ul></section>
</template></main>
</template>
